1: /**
2:  * POST /api/codelab/tutor
3:  *
4:  * Secure Harnessed Socratic AI Tutor for CodeLab.
5:  *
6:  * Security & Pedagogical Invariants:
7:  *  1. Authenticated session required + ICS eligibility enforced.
8:  *  2. Runs within the Lumina LMS AI Harness (3 Concentric Layers).
9:  *  3. Layer 2 Socratic Guardrail prevents direct solution code dumps.
10:  *  4. Layer 2 Rate Limiter prevents API budget exhaustion.
11:  *  5. Autonomous Retry Loop triggers if a draft response is rejected by safety sensors.
12:  *  6. Emits structured trace logs for auditing.
13:  */
14: 
15: import { NextResponse } from "next/server";
16: import { getSession } from "@/lib/auth-session";
17: import { checkActivityEligibility } from "@/lib/activity-eligibility";
18: import { runHarnessedAgent } from "@/lib/harness/core/agent-runner";
19: import { InstituteCode, UserRole } from "@/lib/harness/core/types";
20: 
21: export const dynamic = "force-dynamic";
22: 
23: interface TutorRequestBody {
24:   prompt: string;
25:   templateId?: string;
26:   sourceCode?: string;
27:   errorOutput?: string;
28: }
29: 
30: export async function POST(request: Request) {
31:   try {
32:     // 1. Authenticate Session
33:     const session = await getSession();
34:     if (!session || !session.user) {
35:       return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
36:     }
37: 
38:     // 2. Enforce ICS Eligibility
39:     const eligibility = await checkActivityEligibility();
40:     if (!eligibility || !eligibility.eligible) {
41:       return NextResponse.json(
42:         { error: "Forbidden: CodeLab AI Assistant is exclusive to the Institute of Computer Studies (ICS)." },
43:         { status: 403 }
44:       );
45:     }
46: 
47:     // 3. Parse Request Payload
48:     const body = (await request.json()) as TutorRequestBody;
49:     const { prompt, templateId, sourceCode, errorOutput } = body;
50: 
51:     if (!prompt || prompt.trim().length === 0) {
52:       return NextResponse.json({ error: "Prompt is required." }, { status: 400 });
53:     }
54: 
55:     // Formulate contextualized prompt for the agent
56:     let fullPrompt = prompt;
57:     if (errorOutput) {
58:       fullPrompt += `\n\n[Console Error Output]\n${errorOutput}`;
59:     }
60:     if (sourceCode) {
61:       fullPrompt += `\n\n[Student Source Code Snippet]\n${sourceCode.slice(0, 2000)}`;
62:     }
63: 
64:     // 4. Execute through the Lumina LMS AI Harness
65:     const harnessResult = await runHarnessedAgent({
66:       prompt: fullPrompt,
67:       context: {
68:         userId: session.user.id,
69:         instituteId: session.user.instituteId,
70:         instituteCode: "ics" as InstituteCode,
71:         role: session.user.role as UserRole,
72:       },
73:       maxRetries: 3,
74:       systemDirective:
75:         "You are the Socratic AI CodeLab Tutor at CdM LMS. Guide the student by highlighting conceptual mistakes, off-by-one errors, or syntax issues. NEVER provide complete copy-paste code solutions. Always conclude with a reflective question.",
76:     });
77: 
78:     return NextResponse.json({
79:       success: harnessResult.success,
80:       response: harnessResult.response,
81:       meta: {
82:         attempts: harnessResult.attemptsNeeded,
83:         traceId: harnessResult.traceId,
84:         guardrailFlags: harnessResult.violations,
85:       },
86:     });
87:   } catch (error: any) {
88:     console.error("[CODELAB_TUTOR_API_ERROR]", error);
89:     return NextResponse.json(
90:       { error: "Internal Server Error in AI Tutor Harness", details: error?.message },
91:       { status: 500 }
92:     );
93:   }
94: }
