1: import { NextResponse } from 'next/server';
2: import { db } from '@/lib/db';
3: import { getSessionFromRequest } from '@/lib/api-auth';
4: import { createNotificationsForCourseStudents } from '@/lib/notifications';
5: 
6: export const dynamic = 'force-dynamic';
7: 
8: interface RouteContext {
9:   params: Promise<{ courseId: string }>;
10: }
11: 
12: /**
13:  * POST /api/courses/[courseId]/broadcast
14:  * Broadcasts an urgent notification alert to all enrolled students in a course.
15:  */
16: export async function POST(request: Request, context: RouteContext) {
17:   try {
18:     const session = await getSessionFromRequest(request);
19:     if (!session) {
20:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
21:     }
22: 
23:     const role = (session.user.role as string).toUpperCase();
24:     if (role !== 'PROFESSOR' && role !== 'TEACHER' && role !== 'ADMIN') {
25:       return NextResponse.json({ message: 'Instructors only.' }, { status: 403 });
26:     }
27: 
28:     const { courseId } = await context.params;
29:     const course = await db.course.findUnique({
30:       where: { id: courseId },
31:       select: { id: true, instructorId: true, title: true, code: true },
32:     });
33: 
34:     if (!course) {
35:       return NextResponse.json({ message: 'Course not found.' }, { status: 404 });
36:     }
37: 
38:     if (role !== 'ADMIN' && course.instructorId !== session.user.id) {
39:       return NextResponse.json({ message: 'You are not the instructor for this course.' }, { status: 403 });
40:     }
41: 
42:     const body = await request.json();
43:     const { message, category = 'GENERAL', scope = 'ALL' } = body;
44: 
45:     if (!message || typeof message !== 'string' || message.trim().length === 0) {
46:       return NextResponse.json({ message: 'Broadcast message cannot be empty.' }, { status: 400 });
47:     }
48: 
49:     const approvedCount = await db.enrollment.count({
50:       where: { courseId, status: 'APPROVED' },
51:     });
52: 
53:     const broadcast = await db.notificationBroadcast.create({
54:       data: {
55:         courseId,
56:         senderId: session.user.id,
57:         message: message.trim(),
58:         category: category.toUpperCase(),
59:         scope,
60:         recipientCount: approvedCount,
61:       },
62:       include: {
63:         sender: {
64:           select: { name: true, avatarUrl: true },
65:         },
66:       },
67:     });
68: 
69:     // Notify all approved students in this course
70:     const categoryLabel =
71:       category.toUpperCase() === 'ALERT'
72:         ? 'URGENT ALERT'
73:         : category.toUpperCase() === 'REMINDER'
74:           ? 'REMINDER'
75:           : 'ANNOUNCEMENT';
76: 
77:     await createNotificationsForCourseStudents(courseId, {
78:       type: 'BROADCAST',
79:       title: `[${course.code}] ${categoryLabel}`,
80:       message: message.trim(),
81:       link: `/${courseId}/stream`,
82:     });
83: 
84:     return NextResponse.json({
85:       success: true,
86:       broadcast: {
87:         id: broadcast.id,
88:         message: broadcast.message,
89:         category: broadcast.category,
90:         createdAt: broadcast.createdAt.toISOString(),
91:         senderName: broadcast.sender.name,
92:         senderAvatar: broadcast.sender.avatarUrl,
93:         recipientCount: broadcast.recipientCount,
94:       },
95:     });
96:   } catch (error) {
97:     console.error('COURSE_BROADCAST_POST_ERROR', error);
98:     return NextResponse.json({ message: 'Failed to send broadcast.' }, { status: 500 });
99:   }
100: }
