1: import { NextResponse } from 'next/server';
2: import { db } from '@/lib/db';
3: import { getSessionFromRequest } from '@/lib/api-auth';
4: 
5: export const dynamic = "force-dynamic";
6: 
7: interface RouteContext {
8:   params: Promise<{ courseId: string }>;
9: }
10: 
11: /**
12:  * GET /api/courses/[courseId]/classwork
13:  * Fetches structured syllabus items, attachments, and student's personal submission state.
14:  */
15: export async function GET(request: Request, context: RouteContext) {
16:   try {
17:     const session = await getSessionFromRequest(request);
18:     if (!session) {
19:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
20:     }
21: 
22:     const { courseId } = await context.params;
23: 
24:     const [syllabusItems, studentSubmissions] = await Promise.all([
25:       db.syllabusItem.findMany({
26:         where: { courseId },
27:         include: {
28:           attachments: {
29:             select: {
30:               id: true,
31:               type: true,
32:               url: true,
33:               fileName: true,
34:               fileSize: true,
35:             },
36:           },
37:         },
38:         orderBy: { orderIndex: 'asc' },
39:       }),
40:       db.studentSubmission.findMany({
41:         where: {
42:           studentId: session.user.id,
43:           syllabusItem: { courseId },
44:         },
45:         include: {
46:           attachments: {
47:             select: {
48:               id: true,
49:               type: true,
50:               url: true,
51:               fileName: true,
52:             },
53:           },
54:         },
55:       }),
56:     ]);
57: 
58:     const submissionMap = new Map<string, any>();
59:     studentSubmissions.forEach((sub) => {
60:       submissionMap.set(sub.syllabusItemId, {
61:         id: sub.id,
62:         status: sub.status,
63:         grade: sub.grade,
64:         isReturned: sub.isReturned,
65:         submittedAt: sub.submittedAt ? sub.submittedAt.toISOString() : null,
66:         attachments: sub.attachments,
67:       });
68:     });
69: 
70:     const formattedItems = syllabusItems.map((item) => {
71:       const submission = submissionMap.get(item.id) || null;
72:       return {
73:         id: item.id,
74:         type: item.type, // "ASSIGNMENT" | "QUIZ" | "MATERIAL" | "EXAM"
75:         title: item.title,
76:         description: item.description,
77:         maxPoints: item.maxPoints,
78:         dueDate: item.dueDate ? item.dueDate.toISOString() : null,
79:         orderIndex: item.orderIndex,
80:         attachments: item.attachments,
81:         submission,
82:       };
83:     });
84: 
85:     // Categorize by section/type
86:     const assignments = formattedItems.filter((i) => i.type === 'ASSIGNMENT');
87:     const quizzes = formattedItems.filter((i) => i.type === 'QUIZ');
88:     const materials = formattedItems.filter((i) => i.type === 'MATERIAL');
89:     const others = formattedItems.filter((i) => !['ASSIGNMENT', 'QUIZ', 'MATERIAL'].includes(i.type));
90: 
91:     return NextResponse.json(
92:       {
93:         items: formattedItems,
94:         categories: [
95:           { name: 'Assignments', count: assignments.length, items: assignments },
96:           { name: 'Quizzes & Assessments', count: quizzes.length, items: quizzes },
97:           { name: 'Learning Materials', count: materials.length, items: materials },
98:           ...(others.length > 0 ? [{ name: 'Other Modules', count: others.length, items: others }] : []),
99:         ],
100:       },
101:       {
102:         headers: {
103:           'Cache-Control': 'private, s-maxage=30, stale-while-revalidate=120',
104:         },
105:       }
106:     );
107:   } catch (error) {
108:     console.error('COURSE_CLASSWORK_GET_ERROR', error);
109:     return NextResponse.json({ message: 'Failed to fetch course classwork.' }, { status: 500 });
110:   }
111: }
112: 
113: /**
114:  * POST /api/courses/[courseId]/classwork
115:  * Creates a new syllabus item (Assignment, Quiz, or Material) with optional attachments.
116:  */
117: export async function POST(request: Request, context: RouteContext) {
118:   try {
119:     const session = await getSessionFromRequest(request);
120:     if (!session) {
121:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
122:     }
123: 
124:     const role = (session.user.role as string).toUpperCase();
125:     if (role !== 'PROFESSOR' && role !== 'TEACHER' && role !== 'ADMIN') {
126:       return NextResponse.json({ message: 'Instructors only.' }, { status: 403 });
127:     }
128: 
129:     const { courseId } = await context.params;
130:     const course = await db.course.findUnique({
131:       where: { id: courseId },
132:       select: { id: true, instructorId: true, title: true },
133:     });
134: 
135:     if (!course) {
136:       return NextResponse.json({ message: 'Course not found.' }, { status: 404 });
137:     }
138: 
139:     if (role !== 'ADMIN' && course.instructorId !== session.user.id) {
140:       return NextResponse.json({ message: 'You are not the instructor for this course.' }, { status: 403 });
141:     }
142: 
143:     const body = await request.json();
144:     const {
145:       title,
146:       description = '',
147:       type = 'ASSIGNMENT',
148:       maxPoints,
149:       dueDate,
150:       attachmentUrl,
151:       attachmentName,
152:       attachments,
153:     } = body;
154: 
155:     if (!title || typeof title !== 'string' || title.trim().length === 0) {
156:       return NextResponse.json({ message: 'Title is required.' }, { status: 400 });
157:     }
158: 
159:     const lastItem = await db.syllabusItem.findFirst({
160:       where: { courseId },
161:       orderBy: { orderIndex: 'desc' },
162:       select: { orderIndex: true },
163:     });
164: 
165:     const parsedMaxPoints =
166:       maxPoints !== undefined && maxPoints !== null && !isNaN(Number(maxPoints))
167:         ? Math.max(0, parseInt(String(maxPoints), 10))
168:         : null;
169: 
170:     const parsedDueDate = dueDate ? new Date(dueDate) : null;
171: 
172:     const syllabusItem = await db.syllabusItem.create({
173:       data: {
174:         courseId,
175:         type: type.toUpperCase(),
176:         title: title.trim(),
177:         description: description ? description.trim() : '',
178:         maxPoints: parsedMaxPoints,
179:         dueDate: parsedDueDate,
180:         orderIndex: (lastItem?.orderIndex ?? -1) + 1,
181:       },
182:     });
183: 
184:     // Handle attachments
185:     if (attachmentUrl) {
186:       await db.attachment.create({
187:         data: {
188:           syllabusItemId: syllabusItem.id,
189:           type: 'FILE',
190:           url: attachmentUrl,
191:           fileName: attachmentName || 'Attachment',
192:         },
193:       });
194:     }
195: 
196:     if (Array.isArray(attachments) && attachments.length > 0) {
197:       await db.attachment.createMany({
198:         data: attachments.map((att: { url: string; fileName?: string; type?: string; fileSize?: number }) => ({
199:           syllabusItemId: syllabusItem.id,
200:           type: att.type || 'FILE',
201:           url: att.url,
202:           fileName: att.fileName || 'Attachment',
203:           fileSize: att.fileSize || null,
204:         })),
205:       });
206:     }
207: 
208:     // Notify enrolled students
209:     try {
210:       const { createNotificationsForCourseStudents } = await import('@/lib/notifications');
211:       const itemLabel = syllabusItem.type === 'QUIZ' ? 'quiz' : syllabusItem.type === 'MATERIAL' ? 'material' : 'assignment';
212:       await createNotificationsForCourseStudents(courseId, {
213:         type: 'CLASSWORK',
214:         title: `New ${itemLabel}: ${syllabusItem.title}`,
215:         message: `Your instructor posted a new ${itemLabel} in ${course.title}.`,
216:         link: `/${courseId}/classwork`,
217:       });
218:     } catch (notifErr) {
219:       console.error('NOTIFY_CLASSWORK_ERROR', notifErr);
220:     }
221: 
222:     const createdWithAttachments = await db.syllabusItem.findUnique({
223:       where: { id: syllabusItem.id },
224:       include: { attachments: true },
225:     });
226: 
227:     return NextResponse.json({
228:       success: true,
229:       item: {
230:         ...createdWithAttachments,
231:         dueDate: createdWithAttachments?.dueDate?.toISOString() || null,
232:       },
233:     });
234:   } catch (error) {
235:     console.error('COURSE_CLASSWORK_POST_ERROR', error);
236:     return NextResponse.json({ message: 'Failed to create classwork.' }, { status: 500 });
237:   }
238: }
