1: import { NextResponse } from 'next/server';
2: import { db } from '@/lib/db';
3: import { getSessionFromRequest } from '@/lib/api-auth';
4: import { createNotification } from '@/lib/notifications';
5: 
6: export const dynamic = 'force-dynamic';
7: 
8: interface RouteContext {
9:   params: Promise<{ courseId: string }>;
10: }
11: 
12: /**
13:  * GET /api/courses/[courseId]/enrollments?status=PENDING
14:  * Returns enrollment records for a course (Instructors/Admins only).
15:  */
16: export async function GET(request: Request, context: RouteContext) {
17:   try {
18:     const session = await getSessionFromRequest(request);
19:     if (!session) {
20:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
21:     }
22: 
23:     const role = (session.user.role as string).toUpperCase();
24:     if (role !== 'PROFESSOR' && role !== 'TEACHER' && role !== 'ADMIN') {
25:       return NextResponse.json({ message: 'Instructors only.' }, { status: 403 });
26:     }
27: 
28:     const { courseId } = await context.params;
29:     const { searchParams } = new URL(request.url);
30:     const statusFilter = searchParams.get('status')?.toUpperCase();
31: 
32:     const course = await db.course.findUnique({
33:       where: { id: courseId },
34:       select: { id: true, instructorId: true },
35:     });
36: 
37:     if (!course) {
38:       return NextResponse.json({ message: 'Course not found.' }, { status: 404 });
39:     }
40: 
41:     if (role !== 'ADMIN' && course.instructorId !== session.user.id) {
42:       return NextResponse.json({ message: 'You are not the instructor for this course.' }, { status: 403 });
43:     }
44: 
45:     const whereCondition: Record<string, unknown> = { courseId };
46:     if (statusFilter) {
47:       whereCondition.status = statusFilter;
48:     }
49: 
50:     const enrollments = await db.enrollment.findMany({
51:       where: whereCondition,
52:       include: {
53:         student: {
54:           select: {
55:             id: true,
56:             name: true,
57:             email: true,
58:             studentNumber: true,
59:             avatarUrl: true,
60:           },
61:         },
62:       },
63:       orderBy: { createdAt: 'desc' },
64:     });
65: 
66:     return NextResponse.json({
67:       enrollments: enrollments.map((e) => ({
68:         id: e.id,
69:         status: e.status,
70:         createdAt: e.createdAt.toISOString(),
71:         student: e.student,
72:       })),
73:       totalCount: enrollments.length,
74:     });
75:   } catch (error) {
76:     console.error('COURSE_ENROLLMENTS_GET_ERROR', error);
77:     return NextResponse.json({ message: 'Failed to fetch enrollments.' }, { status: 500 });
78:   }
79: }
80: 
81: /**
82:  * PATCH /api/courses/[courseId]/enrollments
83:  * Approves or rejects a student's enrollment request.
84:  * Body: { enrollmentId: string, action: 'APPROVE' | 'REJECT' }
85:  */
86: export async function PATCH(request: Request, context: RouteContext) {
87:   try {
88:     const session = await getSessionFromRequest(request);
89:     if (!session) {
90:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
91:     }
92: 
93:     const role = (session.user.role as string).toUpperCase();
94:     if (role !== 'PROFESSOR' && role !== 'TEACHER' && role !== 'ADMIN') {
95:       return NextResponse.json({ message: 'Instructors only.' }, { status: 403 });
96:     }
97: 
98:     const { courseId } = await context.params;
99:     const course = await db.course.findUnique({
100:       where: { id: courseId },
101:       select: { id: true, instructorId: true, title: true, code: true },
102:     });
103: 
104:     if (!course) {
105:       return NextResponse.json({ message: 'Course not found.' }, { status: 404 });
106:     }
107: 
108:     if (role !== 'ADMIN' && course.instructorId !== session.user.id) {
109:       return NextResponse.json({ message: 'You are not the instructor for this course.' }, { status: 403 });
110:     }
111: 
112:     const body = await request.json();
113:     const { enrollmentId, action } = body;
114: 
115:     if (!enrollmentId || !action) {
116:       return NextResponse.json({ message: 'enrollmentId and action are required.' }, { status: 400 });
117:     }
118: 
119:     const normalizedAction = action.toUpperCase();
120:     if (normalizedAction !== 'APPROVE' && normalizedAction !== 'REJECT') {
121:       return NextResponse.json({ message: "Action must be 'APPROVE' or 'REJECT'." }, { status: 400 });
122:     }
123: 
124:     const enrollment = await db.enrollment.findUnique({
125:       where: { id: enrollmentId },
126:     });
127: 
128:     if (!enrollment || enrollment.courseId !== courseId) {
129:       return NextResponse.json({ message: 'Enrollment record not found in this course.' }, { status: 404 });
130:     }
131: 
132:     const updated = await db.enrollment.update({
133:       where: { id: enrollmentId },
134:       data: {
135:         status: normalizedAction === 'APPROVE' ? 'APPROVED' : 'REJECTED',
136:       },
137:     });
138: 
139:     // Notify student if approved
140:     if (normalizedAction === 'APPROVE') {
141:       await createNotification({
142:         userId: enrollment.studentId,
143:         type: 'CLASSWORK',
144:         title: `Enrolled in ${course.code}`,
145:         message: `Your enrollment request for ${course.title} has been approved.`,
146:         link: `/${courseId}/classwork`,
147:       });
148:     }
149: 
150:     return NextResponse.json({
151:       success: true,
152:       enrollment: {
153:         id: updated.id,
154:         status: updated.status,
155:       },
156:     });
157:   } catch (error) {
158:     console.error('COURSE_ENROLLMENTS_PATCH_ERROR', error);
159:     return NextResponse.json({ message: 'Failed to update enrollment.' }, { status: 500 });
160:   }
161: }
