1: import { NextRequest, NextResponse } from "next/server";
2: import { getSession } from "@/lib/auth-session";
3: import { executeSkill } from "@/lib/skills";
4: import { exportGradebookSkill } from "@/lib/skills/gradebook-exporter";
5: 
6: export const dynamic = "force-dynamic";
7: 
8: export async function GET(
9:   _req: NextRequest,
10:   { params }: { params: Promise<{ courseId: string }> }
11: ) {
12:   const { courseId } = await params;
13: 
14:   const session = await getSession();
15:   if (!session) {
16:     return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
17:   }
18: 
19:   const role = session.user.role.toUpperCase();
20:   if (role !== "PROFESSOR" && role !== "ADMIN") {
21:     return NextResponse.json({ error: "Forbidden" }, { status: 403 });
22:   }
23: 
24:   const result = await executeSkill("gradebook-exporter", () =>
25:     exportGradebookSkill(courseId)
26:   );
27: 
28:   if (!result.success || !result.data) {
29:     return NextResponse.json(
30:       { error: result.error ?? "Export failed" },
31:       { status: 500 }
32:     );
33:   }
34: 
35:   const { csvContent, fileName } = result.data;
36: 
37:   return new NextResponse(csvContent, {
38:     status: 200,
39:     headers: {
40:       "Content-Type": "text/csv; charset=utf-8",
41:       "Content-Disposition": `attachment; filename="${fileName}"`,
42:       "Cache-Control": "no-store",
43:     },
44:   });
45: }
