11: /**
12:  * GET /api/courses/[courseId]/gradebook
13:  * Fetches student rosters, assignments, submission states, and grade matrix for instructor review.
14:  */
15: export async function GET(request: Request, context: RouteContext) {
16:   try {
17:     const session = await getSessionFromRequest(request);
18:     if (!session) {
19:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
20:     }
21: 
22:     const role = (session.user.role as string).toUpperCase();
23:     if (role !== 'PROFESSOR' && role !== 'TEACHER' && role !== 'ADMIN') {
24:       return NextResponse.json({ message: 'Instructors only.' }, { status: 403 });
25:     }
26: 
27:     const { courseId } = await context.params;
28: 
29:     const course = await db.course.findUnique({
30:       where: { id: courseId },
31:       select: { id: true, instructorId: true, title: true, code: true },
32:     });
33: 
34:     if (!course) {
35:       return NextResponse.json({ message: 'Course not found.' }, { status: 404 });
36:     }
37: 
38:     if (role !== 'ADMIN' && course.instructorId !== session.user.id) {
39:       return NextResponse.json({ message: 'You are not the instructor for this course.' }, { status: 403 });
40:     }
41: 
42:     const [enrollments, syllabusItems, submissions, gradingPolicy] = await Promise.all([
43:       db.enrollment.findMany({
44:         where: { courseId, status: 'APPROVED' },
45:         include: {
46:           student: {
47:             select: { id: true, name: true, email: true, studentNumber: true, avatarUrl: true },
48:           },
49:         },
50:         orderBy: { student: { name: 'asc' } },
51:       }),
52:       db.syllabusItem.findMany({
53:         where: {
54:           courseId,
55:           type: { not: 'MATERIAL' },
56:           maxPoints: { not: null },
57:         },
58:         select: {
59:           id: true,
60:           title: true,
61:           maxPoints: true,
62:           type: true,
63:           dueDate: true,
64:           orderIndex: true,
65:         },
66:         orderBy: { orderIndex: 'asc' },
67:       }),
68:       db.studentSubmission.findMany({
69:         where: { syllabusItem: { courseId } },
70:         select: {
71:           id: true,
72:           syllabusItemId: true,
73:           studentId: true,
74:           grade: true,
75:           status: true,
76:           isReturned: true,
77:           submittedAt: true,
78:           attachments: {
79:             select: { id: true, type: true, url: true, fileName: true },
80:             orderBy: { createdAt: 'asc' },
81:           },
82:         },
83:       }),
84:       db.gradingPolicy.findUnique({
85:         where: { courseId },
86:         include: { weights: true },
87:       }),
88:     ]);
89: 
90:     const students = enrollments.map((e) => ({
91:       id: e.student.id,
92:       name: e.student.name,
93:       email: e.student.email,
94:       studentNumber: e.student.studentNumber,
95:       avatarUrl: e.student.avatarUrl,
96:     }));
97: 
98:     const assignments = syllabusItems.map((item) => ({
99:       id: item.id,
100:       title: item.title,
101:       maxPoints: item.maxPoints,
102:       type: item.type,
103:       dueDate: item.dueDate?.toISOString() || null,
104:     }));
105: 
106:     // Build nested grade matrix: grades[studentId][assignmentId]
107:     const grades: Record<
108:       string,
109:       Record<
110:         string,
111:         {
112:           submissionId: string | null;
113:           grade: number | null;
114:           status: string | null;
115:           isReturned: boolean;
116:           submittedAt: string | null;
117:           attachments: Array<{ id: string; type: string; url: string; fileName: string }>;
118:         }
119:       >
120:     > = {};
121: 
122:     for (const student of students) {
123:       grades[student.id] = {};
124:       for (const assignment of assignments) {
125:         grades[student.id][assignment.id] = {
126:           submissionId: null,
127:           grade: null,
128:           status: null,
129:           isReturned: false,
130:           submittedAt: null,
131:           attachments: [],
132:         };
133:       }
134:     }
135: 
136:     for (const sub of submissions) {
137:       if (grades[sub.studentId]?.[sub.syllabusItemId] !== undefined) {
138:         grades[sub.studentId][sub.syllabusItemId] = {
139:           submissionId: sub.id,
140:           grade: sub.grade,
141:           status: sub.status,
142:           isReturned: sub.isReturned,
143:           submittedAt: sub.submittedAt ? sub.submittedAt.toISOString() : null,
144:           attachments: sub.attachments,
145:         };
146:       }
147:     }
148: 
149:     return NextResponse.json({
150:       course: { id: course.id, title: course.title, code: course.code },
151:       students,
152:       assignments,
153:       grades,
154:       gradingPolicy: gradingPolicy
155:         ? {
156:             weights: gradingPolicy.weights.map((w) => ({
157:               category: w.category,
158:               weightPercentage: w.weightPercentage,
159:             })),
160:           }
161:         : null,
162:     });
163:   } catch (error) {
164:     console.error('GRADEBOOK_GET_ERROR', error);
165:     return NextResponse.json({ message: 'Failed to fetch gradebook data.' }, { status: 500 });
166:   }
167: }
