1: import { NextResponse } from 'next/server';
2: import { db } from '@/lib/db';
3: import { getSessionFromRequest } from '@/lib/api-auth';
4: 
5: export const dynamic = "force-dynamic";
6: 
7: interface RouteContext {
8:   params: Promise<{ courseId: string }>;
9: }
10: 
11: /**
12:  * GET /api/courses/[courseId]/grades
13:  * Fetches student's score breakdown, completion metrics, and instructor feedback notes.
14:  */
15: export async function GET(request: Request, context: RouteContext) {
16:   try {
17:     const session = await getSessionFromRequest(request);
18:     if (!session) {
19:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
20:     }
21: 
22:     const { courseId } = await context.params;
23: 
24:     const [gradableItems, studentSubmissions, feedbackComments] = await Promise.all([
25:       db.syllabusItem.findMany({
26:         where: {
27:           courseId,
28:           type: { not: 'MATERIAL' },
29:           maxPoints: { not: null },
30:         },
31:         select: {
32:           id: true,
33:           title: true,
34:           type: true,
35:           maxPoints: true,
36:           dueDate: true,
37:         },
38:         orderBy: { dueDate: 'asc' },
39:       }),
40:       db.studentSubmission.findMany({
41:         where: {
42:           studentId: session.user.id,
43:           syllabusItem: { courseId },
44:         },
45:         select: {
46:           id: true,
47:           syllabusItemId: true,
48:           status: true,
49:           grade: true,
50:           isReturned: true,
51:           submittedAt: true,
52:         },
53:       }),
54:       db.privateComment.findMany({
55:         where: {
56:           courseId,
57:           recipientId: session.user.id,
58:         },
59:         include: {
60:           sender: {
61:             select: { name: true, avatarUrl: true },
62:           },
63:         },
64:         orderBy: { createdAt: 'desc' },
65:         take: 10,
66:       }),
67:     ]);
68: 
69:     const subMap = new Map<string, any>();
70:     studentSubmissions.forEach((sub) => {
71:       subMap.set(sub.syllabusItemId, sub);
72:     });
73: 
74:     let totalPossiblePoints = 0;
75:     let totalEarnedPoints = 0;
76:     let completedCount = 0;
77:     let gradedCount = 0;
78:     let missingCount = 0;
79: 
80:     const items = gradableItems.map((item) => {
81:       const sub = subMap.get(item.id);
82:       const maxPts = item.maxPoints || 100;
83:       const score = typeof sub?.grade === 'number' ? sub.grade : null;
84:       const isSubmitted = sub?.status === 'SUBMITTED' || sub?.status === 'GRADED';
85:       const isPastDue = item.dueDate ? new Date(item.dueDate) < new Date() : false;
86: 
87:       if (score !== null) {
88:         totalEarnedPoints += score;
89:         totalPossiblePoints += maxPts;
90:         gradedCount++;
91:         completedCount++;
92:       } else if (isSubmitted) {
93:         completedCount++;
94:       } else if (isPastDue) {
95:         missingCount++;
96:       }
97: 
98:       return {
99:         id: item.id,
100:         title: item.title,
101:         type: item.type,
102:         maxPoints: maxPts,
103:         score,
104:         status: score !== null ? 'GRADED' : isSubmitted ? 'SUBMITTED' : isPastDue ? 'MISSING' : 'ASSIGNED',
105:         dueDate: item.dueDate ? item.dueDate.toISOString() : null,
106:       };
107:     });
108: 
109:     const averagePercentage =
110:       totalPossiblePoints > 0
111:         ? Math.round((totalEarnedPoints / totalPossiblePoints) * 100)
112:         : null;
113: 
114:     let letterGrade = 'N/A';
115:     if (averagePercentage !== null) {
116:       if (averagePercentage >= 90) letterGrade = 'A';
117:       else if (averagePercentage >= 80) letterGrade = 'B';
118:       else if (averagePercentage >= 70) letterGrade = 'C';
119:       else if (averagePercentage >= 60) letterGrade = 'D';
120:       else letterGrade = 'F';
121:     }
122: 
123:     return NextResponse.json(
124:       {
125:         summary: {
126:           averagePercentage,
127:           letterGrade,
128:           totalEarnedPoints,
129:           totalPossiblePoints,
130:           totalItems: gradableItems.length,
131:           completedCount,
132:           gradedCount,
133:           missingCount,
134:         },
135:         items,
136:         feedback: feedbackComments.map((f) => ({
137:           id: f.id,
138:           content: f.content,
139:           senderName: f.sender.name,
140:           senderAvatar: f.sender.avatarUrl,
141:           createdAt: f.createdAt.toISOString(),
142:         })),
143:       },
144:       {
145:         headers: {
146:           'Cache-Control': 'private, s-maxage=30, stale-while-revalidate=120',
147:         },
148:       }
149:     );
150:   } catch (error) {
151:     console.error('COURSE_GRADES_GET_ERROR', error);
152:     return NextResponse.json({ message: 'Failed to fetch course grades.' }, { status: 500 });
153:   }
154: }
